import{_ as e,c as s,o as t,ag as r}from"./chunks/framework.Cycwnjj0.js";const a="/assets/dashboard-of-azonpress.CzSJRhyG.webp",g=JSON.parse('{"title":"Dashboard of AzonPress","description":"","frontmatter":{},"headers":[],"relativePath":"guide/getting-started/dashboard-of-azonpress.md","filePath":"guide/getting-started/dashboard-of-azonpress.md"}'),i={name:"guide/getting-started/dashboard-of-azonpress.md"};function n(l,o,d,h,u,p){return t(),s("div",null,[...o[0]||(o[0]=[r('<h1 id="dashboard-of-azonpress" tabindex="-1">Dashboard of AzonPress <a class="header-anchor" href="#dashboard-of-azonpress" aria-label="Permalink to &quot;Dashboard of AzonPress&quot;">​</a></h1><p>The <strong>Dashboard</strong> of AzonPress displays the <strong>Overall Click Reports</strong> for all your affiliate products, <strong>Affiliate Statistics</strong>, and a <strong>Usage Guide</strong> to make the plugin more user-friendly. This article will guide you through the explanation of the main <strong>Dashboard</strong> of <strong>AzonPress</strong>.</p><h2 id="dashboard-of-azonpress-1" tabindex="-1">Dashboard of AzonPress <a class="header-anchor" href="#dashboard-of-azonpress-1" aria-label="Permalink to &quot;Dashboard of AzonPress&quot;">​</a></h2><p>To learn about all the available options under the Dashboard of AzonPress, follow the steps with a screenshot below –</p><p>First, go to <strong>Dashboard</strong> from the <strong>WordPress Sidebar</strong> or <strong>AzonPress Navbar</strong> and the main dashboard page will open.</p><p>Here, you will get all the options of AzonPress Dashboard for all your Products. All the options are briefly explained below:</p><ol><li><p><strong>Click Tracking Overview</strong>: With this option, you will get an overview of the clicks you receive from your affiliate products. Such as –</p><ul><li>Total clicks: All the clicks received from all your products on your site.</li><li>Unique clicks: All the unique clicks you received from all your products.</li><li>Total Views: All the views you got from all your products on your site.</li><li>Total countries: All the number of countries from where you got the clicks.</li></ul></li><li><p><strong>Click Tracking Report</strong>: Here, you can see your graph of total click reports for the recent days in a line chart.</p></li><li><p><strong>Affiliate Statistic</strong>: This option provides an overall statistic about how many product tables you have on your site and the activity status of your Amazon API Key.</p></li><li><p><strong>View Usage Guide</strong>: By clicking this button, you will go to the <strong>Usage Guide</strong> section where you can get a few necessary documentation providing proper guidelines to use this plugin.</p></li></ol><p><img src="'+a+'" alt="Dashboard of AzonPress"></p><p>If you have any further questions, concerns, or suggestions, please do not hesitate to contact our support team. Thank you.</p><hr>',10)])])}const f=e(i,[["render",n]]);export{g as __pageData,f as default};
